SourceCode.Declaration:
/// <summary>
/// Auto process and print for bill of lading
/// </summary>
class AVAAutoPrintBillOfLadingService
{
}

Method.Source:
/// <summary>
/// Execute thecomplete process
/// </summary>
/// <param name = "_contract"> Data contract</param>
public void autoPrint(AVAAutoPrintBillOfLadingContract _contract)
{
    Query           query;
    QueryRun        queryRun;
    WHSLoadTable    loadTable;

    query       = _contract.getQuery();
    queryRun    = new QueryRun(query)       ;

    while (queryRun.next())
    {
        loadTable =  queryRun.get(tableNum(WHSLoadTable));

        ttsbegin;
        this.peUpdateToPrint(loadTable);
        this.printBOLForAllLoad(loadTable);
        this.updateLoadTable(loadTable);
        ttscommit;
    }
}

/// <summary>
/// Pre process for reprinting
/// </summary>
/// <param name = "_loadTable"> WHSLoadTable record </param>
protected void peUpdateToPrint(WHSLoadTable _loadTable)
{
    WHSShipmentTable    shipmentTable;
    WHSLoadLine         loadLine;

    while select BillOfLadingId from shipmentTable
        where shipmentTable.LoadId == _loadTable.LoadId
           && shipmentTable.BillOfLadingId
        exists join loadLine
            where shipmentTable.ShipmentId == loadLine.ShipmentId
    {
        this.cleanUpWHSBillOfLadingId(shipmentTable.BillOfLadingId);
    }
}

/// <summary>
/// delte the data for a WHSBillOfLadingId
/// </summary>
/// <param name = "_billOfLadingId">WHSBillOfLadingId</param>
protected void cleanUpWHSBillOfLadingId(WHSBillOfLadingId _billOfLadingId)
{
    WHSBillOfLading billOfLading;

    billOfLading = WHSBillOfLading::find(_billOfLadingId, true);

    if (billOfLading)
    {
        billOfLading.delete();
    }
}

/// <summary>
/// Execute the printing for WHSLoadTable
/// </summary>
/// <param name = "_loadTable">WHSLoadTable record</param>
protected void printBOLForAllLoad(WHSLoadTable _loadTable)
{
    List loadIdList = new List(Types::String);

    loadIdList.addEnd(_loadTable.LoadId);

    WHSShipConfirm::printBOLForAllLoads(loadIdList);
}

/// <summary>
/// Update the WHSLoadTable after executting the printing
/// </summary>
/// <param name = "_loadTable">WHSLoadTable record</param>
protected void updateLoadTable(WHSLoadTable _loadTable)
{
    _loadTable.selectForUpdate(true);
    _loadTable.AVAPrinted   = NoYes::Yes;
    _loadTable.AVAPrintedOn = DateTimeUtil::utcNow();
    _loadTable.update();
}
